    ["C_Traits.GetTraitDescription(129613, 4)"] = "1: string Increases damage done by your melee abilities on Bleeding targets by 8%.",
    ["C_Traits.GetTraitDescription(129613, 5)"] = "1: string Increases damage done by your melee abilities on Bleeding targets by 10%.",
    ["C_Traits.GetTraitDescription(129614, 1)"] = "1: string Increases your dodge chance by 1%, and gives you a 20% chance to gain 5 Rage each time you dodge.",
    ["C_Traits.GetTraitDescription(129614, 2)"] = "1: string Increases your dodge chance by 2%, and gives you a 40% chance to gain 5 Rage each time you dodge.",
    ["C_Traits.GetTraitDescription(129614, 3)"] = "1: string Increases your dodge chance by 3%, and gives you a 60% chance to gain 5 Rage each time you dodge.",
