    ["C_Traits.GetTraitDescription(129615, 1)"] = "1: string While in Cat Form, Bear Form, or Dire Bear Form, the Leader of the Pack increases the melee and ranged Critical Strike chance of all party or raid members within 45 yards by 3%.",
    ["C_Traits.GetTraitDescription(129616, 1)"] = "1: string |CFFFF2020Requires Cat Form, Bear Form, Dire Bear Form|R\r\nCauses your Primal Bite ability to strike up to 3 targets, removes its cooldown, and increases the critical strike chance of your Combo Point-generating abilities by 100%. Clears and grants immunity to Fear effects for the duration. Lasts 15 sec.",
    ["C_Traits.GetTraitDescription(129617, 1)"] = "1: string Gives your Arcane and Nature spells a 14% chance to not lose casting time when you take damage.",
    ["C_Traits.GetTraitDescription(129617, 2)"] = "1: string Gives your Arcane and Nature spells a 28% chance to not lose casting time when you take damage.",
    ["C_Traits.GetTraitDescription(129617, 3)"] = "1: string Gives your Arcane and Nature spells a 42% chance to not lose casting time when you take damage.",
    ["C_Traits.GetTraitDescription(129617, 4)"] = "1: string Gives your Arcane and Nature spells a 56% chance to not lose casting time when you take damage.",
    ["C_Traits.GetTraitDescription(129617, 5)"] = "1: string Gives your Arcane and Nature spells a 70% chance to not lose casting time when you take damage.",
    ["C_Traits.GetTraitDescription(129618, 1)"] = "1: string Gives you a 20% chance to gain 10 Rage when shapeshifting into Bear Form or Dire Bear Form. Shapeshifting into Cat Form restores 20% of the Energy you had when last in Cat Form, plus 2 Energy per second spent outside Bear Form or Dire Bear Form, up to 20 Energy.",
    ["C_Traits.GetTraitDescription(129618, 2)"] = "1: string Gives you a 40% chance to gain 10 Rage when shapeshifting into Bear Form or Dire Bear Form. Shapeshifting into Cat Form restores 40% of the Energy you had when last in Cat Form, plus 4 Energy per second spent outside Bear Form or Dire Bear Form, up to 40 Energy.",
    ["C_Traits.GetTraitDescription(129618, 3)"] = "1: string Gives you a 60% chance to gain 10 Rage when shapeshifting into Bear Form or Dire Bear Form. Shapeshifting into Cat Form restores 60% of the Energy you had when last in Cat Form, plus 6 Energy per second spent outside Bear Form or Dire Bear Form, up to 60 Energy.",
    ["C_Traits.GetTraitDescription(129618, 4)"] = "1: string Gives you a 80% chance to gain 10 Rage when shapeshifting into Bear Form or Dire Bear Form. Shapeshifting into Cat Form restores 80% of the Energy you had when last in Cat Form, plus 8 Energy per second spent outside Bear Form or Dire Bear Form, up to 80 Energy.",
    ["C_Traits.GetTraitDescription(129618, 5)"] = "1: string Gives you a 100% chance to gain 10 Rage when shapeshifting into Bear Form or Dire Bear Form. Shapeshifting into Cat Form restores 100% of the Energy you had when last in Cat Form, plus 10 Energy per second spent outside Bear Form or Dire Bear Form, up to 100 Energy.",
    ["C_Traits.GetTraitDescription(129621, 1)"] = "1: string While Aspect of the Hawk is active, Auto Shot has a 2% chance of increasing ranged attack speed by 30% for 12 sec. While Aspect of the Beast is active, all melee auto attacks have a 2% chance of increasing melee attack speed by 30% for 12 sec.",
    ["C_Traits.GetTraitDescription(129621, 2)"] = "1: string While Aspect of the Hawk is active, Auto Shot has a 4% chance of increasing ranged attack speed by 30% for 12 sec. While Aspect of the Beast is active, all melee auto attacks have a 4% chance of increasing melee attack speed by 30% for 12 sec.",
    ["C_Traits.GetTraitDescription(129621, 3)"] = "1: string While Aspect of the Hawk is active, Auto Shot has a 6% chance of increasing ranged attack speed by 30% for 12 sec. While Aspect of the Beast is active, all melee auto attacks have a 6% chance of increasing melee attack speed by 30% for 12 sec.",
    ["C_Traits.GetTraitDescription(129621, 4)"] = "1: string While Aspect of the Hawk is active, Auto Shot has a 8% chance of increasing ranged attack speed by 30% for 12 sec. While Aspect of the Beast is active, all melee auto attacks have a 8% chance of increasing melee attack speed by 30% for 12 sec.",
    ["C_Traits.GetTraitDescription(129621, 5)"] = "1: string While Aspect of the Hawk is active, Auto Shot has a 10% chance of increasing ranged attack speed by 30% for 12 sec. While Aspect of the Beast is active, all melee auto attacks have a 10% chance of increasing melee attack speed by 30% for 12 sec.",
    ["C_Traits.GetTraitDescription(129622, 1)"] = "1: string Send your pet into a rage causing 50% additional damage for 18 sec.  While enraged, the beast does not feel pity or remorse or fear and it cannot be stopped unless killed.",
    ["C_Traits.GetTraitDescription(129623, 1)"] = "1: string Gives your pet a 20% chance to gain a 30% attack speed increase for 8 sec after dealing a critical strike.",
